-- P6 Voice: durable, one-time ConversationRelay session references.
--
-- The opaque bearer value is generated by aidream and never crosses this
-- database boundary. Only its SHA-256 digest is written to the existing
-- platform.activity_log evidence ledger. The canonical call remains
-- crm.interaction; no parallel session, consent, or transcript table exists.

create unique index if not exists activity_log_voice_session_reference_hash_uidx
  on platform.activity_log ((metadata ->> 'reference_sha256'))
  where action = 'voice.agent.session_reference.issued';

create unique index if not exists activity_log_voice_session_reference_session_uidx
  on platform.activity_log ((metadata ->> 'session_id'))
  where action = 'voice.agent.session_reference.issued';

create unique index if not exists activity_log_voice_session_consumed_hash_uidx
  on platform.activity_log ((metadata ->> 'reference_sha256'))
  where action = 'voice.agent.session_reference.consumed';

create unique index if not exists activity_log_voice_provider_session_uidx
  on platform.activity_log ((metadata ->> 'provider_session_id'))
  where action = 'voice.agent.session_reference.consumed';

create or replace function communication.issue_voice_agent_session_reference(
  p_reference_sha256 text,
  p_session_id uuid,
  p_expires_at timestamptz,
  p_interaction_id uuid,
  p_chat_conversation_id uuid,
  p_consent_event_id bigint,
  p_slot_id uuid,
  p_slot_key text,
  p_definition_agent_id uuid,
  p_agent_version_id uuid,
  p_slot_provenance text,
  p_slot_config_overrides jsonb default null,
  p_transport text default 'conversation_relay'
)
returns table (
  event_id bigint,
  session_id uuid,
  expires_at timestamptz
)
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_interaction crm.interaction%rowtype;
  v_consent platform.activity_log%rowtype;
  v_conversation chat.conversation%rowtype;
  v_event_id bigint;
  v_now timestamptz := clock_timestamp();
  v_metadata jsonb;
begin
  if p_reference_sha256 !~ '^sha256:[0-9a-f]{64}$'
     or p_session_id is null
     or p_expires_at is null
     or p_expires_at <= v_now
     or p_expires_at > v_now + interval '10 minutes'
     or p_interaction_id is null
     or p_chat_conversation_id is null
     or p_consent_event_id is null
     or p_slot_id is null
     or p_slot_key !~ '^[a-z][a-z0-9_]*(\.[a-z][a-z0-9_]*)+$'
     or p_definition_agent_id is null
     or p_slot_provenance not in ('system', 'org', 'user', 'run')
     or p_transport <> 'conversation_relay'
     or (p_slot_config_overrides is not null and jsonb_typeof(p_slot_config_overrides) <> 'object') then
    raise exception 'Complete exact Voice session reference inputs are required'
      using errcode = '22023';
  end if;

  select interaction.* into v_interaction
  from crm.interaction interaction
  where interaction.id = p_interaction_id
    and interaction.channel_code = 'call'
    and interaction.deleted_at is null
    and interaction.party_id is not null
    and interaction.contact_point_id is not null
    and interaction.organization_id is not null
    and interaction.recording_owner_id is not null
    and nullif(interaction.provider, '') is not null
    and nullif(interaction.provider_account_id, '') is not null
    and nullif(interaction.provider_interaction_id, '') is not null
    and nullif(interaction.program_key, '') is not null
  for update;
  if not found then
    raise exception 'No exact canonical Voice interaction matched'
      using errcode = 'P0002';
  end if;

  select activity.* into v_consent
  from platform.activity_log activity
  where activity.id = p_consent_event_id
    and activity.action = 'voice.call.consent'
    and activity.entity_type = 'crm_interaction'
    and activity.entity_id = v_interaction.id
    and activity.organization_id = v_interaction.organization_id
    and activity.actor_id = v_interaction.recording_owner_id
    and (activity.metadata ->> 'consented')::boolean is true
    and activity.metadata ->> 'provider' = v_interaction.provider
    and activity.metadata ->> 'provider_account_id' = v_interaction.provider_account_id
    and activity.metadata ->> 'provider_call_id' = v_interaction.provider_interaction_id
    and activity.metadata ->> 'program_key' = v_interaction.program_key
    and activity.metadata is not distinct from v_interaction.attributes -> 'voice_consent';
  if not found then
    raise exception 'No exact durable Voice consent evidence matched'
      using errcode = 'P0002';
  end if;

  select conversation.* into v_conversation
  from chat.conversation conversation
  where conversation.id = p_chat_conversation_id
    and conversation.organization_id = v_interaction.organization_id
    and conversation.created_by = v_interaction.recording_owner_id
    and conversation.initial_agent_id = p_definition_agent_id
    and conversation.initial_agent_version_id is not distinct from p_agent_version_id
    and conversation.deleted_at is null
    and conversation.is_ephemeral is false
  for update;
  if not found then
    raise exception 'No exact persisted Voice chat conversation matched'
      using errcode = 'P0002';
  end if;

  if not exists (
    select 1
    from agent.slot_definition slot
    where slot.id = p_slot_id
      and slot.slot_key = p_slot_key
      and slot.is_enabled is true
      and slot.deleted_at is null
  ) or not exists (
    select 1
    from agent.definition definition
    where definition.id = p_definition_agent_id
      and definition.is_active is true
      and definition.is_archived is false
      and definition.deleted_at is null
  ) or (
    p_agent_version_id is not null
    and not exists (
      select 1
      from agent.definition_version version
      where version.id = p_agent_version_id
        and version.agent_id = p_definition_agent_id
        and version.deleted_at is null
    )
  ) then
    raise exception 'Voice slot snapshot is not exactly runnable'
      using errcode = 'P0002';
  end if;

  v_metadata := jsonb_build_object(
    'reference_sha256', p_reference_sha256,
    'session_id', p_session_id,
    'expires_at', p_expires_at,
    'transport', p_transport,
    'interaction_id', v_interaction.id,
    'chat_conversation_id', v_conversation.id,
    'organization_id', v_interaction.organization_id,
    'party_id', v_interaction.party_id,
    'contact_point_id', v_interaction.contact_point_id,
    'actor_user_id', v_interaction.recording_owner_id,
    'provider', v_interaction.provider,
    'provider_account_id', v_interaction.provider_account_id,
    'provider_call_id', v_interaction.provider_interaction_id,
    'program_key', v_interaction.program_key,
    'consent_event_id', v_consent.id,
    'consent', v_consent.metadata,
    'slot_id', p_slot_id,
    'slot_key', p_slot_key,
    'definition_agent_id', p_definition_agent_id,
    'agent_version_id', p_agent_version_id,
    'slot_provenance', p_slot_provenance,
    'slot_config_overrides', p_slot_config_overrides
  );

  insert into platform.activity_log (
    organization_id, entity_type, entity_id, action, actor_id, occurred_at, metadata
  ) values (
    v_interaction.organization_id,
    'crm_interaction',
    v_interaction.id,
    'voice.agent.session_reference.issued',
    v_interaction.recording_owner_id,
    v_now,
    v_metadata
  ) returning id into v_event_id;

  return query select v_event_id, p_session_id, p_expires_at;
end;
$$;

create or replace function communication.consume_voice_agent_session_reference(
  p_reference_sha256 text,
  p_provider text,
  p_provider_account_id text,
  p_provider_call_id text,
  p_provider_session_id text
)
returns table (
  binding jsonb,
  launch_facts jsonb
)
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_issued platform.activity_log%rowtype;
  v_consumed_id bigint;
  v_metadata jsonb;
  v_now timestamptz := clock_timestamp();
  v_binding jsonb;
begin
  if p_reference_sha256 !~ '^sha256:[0-9a-f]{64}$'
     or nullif(btrim(p_provider), '') is null
     or nullif(btrim(p_provider_account_id), '') is null
     or nullif(btrim(p_provider_call_id), '') is null
     or nullif(btrim(p_provider_session_id), '') is null then
    return;
  end if;

  select issued.* into v_issued
  from platform.activity_log issued
  where issued.action = 'voice.agent.session_reference.issued'
    and issued.metadata ->> 'reference_sha256' = p_reference_sha256
  for update;
  if not found
     or (v_issued.metadata ->> 'expires_at')::timestamptz <= v_now
     or v_issued.metadata ->> 'transport' <> 'conversation_relay'
     or v_issued.metadata ->> 'provider' <> p_provider
     or v_issued.metadata ->> 'provider_account_id' <> p_provider_account_id
     or v_issued.metadata ->> 'provider_call_id' <> p_provider_call_id
     or exists (
       select 1
       from platform.activity_log consumed
       where consumed.action = 'voice.agent.session_reference.consumed'
         and consumed.metadata ->> 'reference_sha256' = p_reference_sha256
     ) then
    return;
  end if;

  if not exists (
    select 1
    from crm.interaction interaction
    where interaction.id = (v_issued.metadata ->> 'interaction_id')::uuid
      and interaction.channel_code = 'call'
      and interaction.organization_id = (v_issued.metadata ->> 'organization_id')::uuid
      and interaction.party_id = (v_issued.metadata ->> 'party_id')::uuid
      and interaction.contact_point_id = (v_issued.metadata ->> 'contact_point_id')::uuid
      and interaction.recording_owner_id = (v_issued.metadata ->> 'actor_user_id')::uuid
      and interaction.provider = p_provider
      and interaction.provider_account_id = p_provider_account_id
      and interaction.provider_interaction_id = p_provider_call_id
      and interaction.program_key = v_issued.metadata ->> 'program_key'
      and interaction.attributes -> 'voice_consent' = v_issued.metadata -> 'consent'
      and interaction.deleted_at is null
  ) or not exists (
    select 1
    from platform.activity_log consent
    where consent.id = (v_issued.metadata ->> 'consent_event_id')::bigint
      and consent.action = 'voice.call.consent'
      and consent.entity_id = (v_issued.metadata ->> 'interaction_id')::uuid
      and consent.organization_id = (v_issued.metadata ->> 'organization_id')::uuid
      and consent.actor_id = (v_issued.metadata ->> 'actor_user_id')::uuid
      and consent.metadata = v_issued.metadata -> 'consent'
  ) or not exists (
    select 1
    from chat.conversation conversation
    where conversation.id = (v_issued.metadata ->> 'chat_conversation_id')::uuid
      and conversation.organization_id = (v_issued.metadata ->> 'organization_id')::uuid
      and conversation.created_by = (v_issued.metadata ->> 'actor_user_id')::uuid
      and conversation.initial_agent_id = (v_issued.metadata ->> 'definition_agent_id')::uuid
      and conversation.initial_agent_version_id is not distinct from
        nullif(v_issued.metadata ->> 'agent_version_id', '')::uuid
      and conversation.deleted_at is null
      and conversation.is_ephemeral is false
  ) or not exists (
    select 1
    from agent.slot_definition slot
    where slot.id = (v_issued.metadata ->> 'slot_id')::uuid
      and slot.slot_key = v_issued.metadata ->> 'slot_key'
      and slot.is_enabled is true
      and slot.deleted_at is null
  ) or not exists (
    select 1
    from agent.definition definition
    where definition.id = (v_issued.metadata ->> 'definition_agent_id')::uuid
      and definition.is_active is true
      and definition.is_archived is false
      and definition.deleted_at is null
  ) or (
    v_issued.metadata ->> 'agent_version_id' is not null
    and not exists (
      select 1
      from agent.definition_version version
      where version.id = (v_issued.metadata ->> 'agent_version_id')::uuid
        and version.agent_id = (v_issued.metadata ->> 'definition_agent_id')::uuid
        and version.deleted_at is null
    )
  ) then
    return;
  end if;

  v_metadata := v_issued.metadata || jsonb_build_object(
    'issued_event_id', v_issued.id,
    'provider_session_id', p_provider_session_id,
    'consumed_at', v_now
  );
  insert into platform.activity_log (
    organization_id, entity_type, entity_id, action, actor_id, occurred_at, metadata
  ) values (
    v_issued.organization_id,
    v_issued.entity_type,
    v_issued.entity_id,
    'voice.agent.session_reference.consumed',
    v_issued.actor_id,
    v_now,
    v_metadata
  ) returning id into v_consumed_id;

  v_binding := jsonb_build_object(
    'session_id', v_issued.metadata ->> 'session_id',
    'transport', v_issued.metadata ->> 'transport',
    'call', jsonb_build_object(
      'provider', v_issued.metadata ->> 'provider',
      'provider_account_id', v_issued.metadata ->> 'provider_account_id',
      'provider_call_id', v_issued.metadata ->> 'provider_call_id'
    ),
    'interaction_id', v_issued.metadata ->> 'interaction_id',
    'chat_conversation_id', v_issued.metadata ->> 'chat_conversation_id',
    'organization_id', v_issued.metadata ->> 'organization_id',
    'party_id', v_issued.metadata ->> 'party_id',
    'contact_point_id', v_issued.metadata ->> 'contact_point_id',
    'actor_user_id', v_issued.metadata ->> 'actor_user_id',
    'agent', jsonb_build_object(
      'slot_key', v_issued.metadata ->> 'slot_key',
      'slot_id', v_issued.metadata ->> 'slot_id',
      'definition_agent_id', v_issued.metadata ->> 'definition_agent_id',
      'agent_version_id', v_issued.metadata -> 'agent_version_id',
      'provenance', v_issued.metadata ->> 'slot_provenance',
      'config_overrides', v_issued.metadata -> 'slot_config_overrides'
    ),
    'consent', jsonb_build_object(
      'provider', v_issued.metadata #>> '{consent,provider}',
      'provider_account_id', v_issued.metadata #>> '{consent,provider_account_id}',
      'provider_call_id', v_issued.metadata #>> '{consent,provider_call_id}',
      'provider_event_key', v_issued.metadata #>> '{consent,provider_event_key}',
      'disclosure_version', v_issued.metadata #>> '{consent,disclosure_version}',
      'disclosure_text_sha256', replace(
        v_issued.metadata #>> '{consent,disclosure_text_hash}', 'sha256:', ''
      ),
      'disclosed_at', v_issued.metadata #> '{consent,disclosed_at}',
      'response_kind', v_issued.metadata #>> '{consent,response_kind}',
      'response_value', v_issued.metadata #>> '{consent,response_value}',
      'consented_at', v_issued.metadata #> '{consent,consented_at}',
      'source', v_issued.metadata #>> '{consent,source}'
    )
  );

  return query select
    v_binding,
    jsonb_build_object(
      'session_binding_match_count', 1,
      'consent_event_match_count', 1,
      'slot_resolution_match_count', 1,
      'active_global', 0,
      'active_program', 0,
      'active_party', 0,
      'estimated_cost_today_usd', 0
    );
end;
$$;

revoke all on function communication.issue_voice_agent_session_reference(
  text, uuid, timestamptz, uuid, uuid, bigint, uuid, text, uuid, uuid, text, jsonb, text
) from public, anon, authenticated;
revoke all on function communication.consume_voice_agent_session_reference(
  text, text, text, text, text
) from public, anon, authenticated;

grant execute on function communication.issue_voice_agent_session_reference(
  text, uuid, timestamptz, uuid, uuid, bigint, uuid, text, uuid, uuid, text, jsonb, text
) to service_role;
grant execute on function communication.consume_voice_agent_session_reference(
  text, text, text, text, text
) to service_role;
